import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"Tabs","description":"","frontmatter":{},"headers":[],"relativePath":"components/tabs.md","filePath":"components/tabs.md"}'),s={name:"components/tabs.md"};function d(n,e,i,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h1><p>Tabs switch between the views of one place, or between the pages of a group.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use tabs without <code>href</code> to switch a view on the same page, and tabs with <code>href</code> for pages that belong together, such as the pages of the settings. Put them in a <a href="./toolbar">Toolbar</a> to use them as the head of a panel. For two to four values of a setting, use a <a href="./segmented">Segmented</a> instead.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tabs</code></td><td>required</td><td><code>{ id, label, href? }[]</code></td></tr><tr><td><code>current</code></td><td>required</td><td>The id of the current tab</td></tr><tr><td><code>label</code></td><td></td><td>The name of the set of tabs</td></tr><tr><td><code>onselect</code></td><td></td><td>Called with the id of the tab that is opened</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A tab is as tall as a list item, with pad-md at the sides and its label trimmed to its ink, muted until it is current. The current tab has <code>aria-current=&quot;page&quot;</code> and a double blue line along its bottom, drawn inside it, so its height does not change. The tabs have a line along their bottom, which counts as a line as a <a href="./divider">Divider</a> does: what follows them is placed as after a Divider, so a section after them starts as after a line and text right after them is trimmed to its ink. On a page the content under the rule is gap-lg away; inside a Panel the next SectionHeader&#39;s pad-md is the distance. Inside a Toolbar they take the toolbar&#39;s height and its line instead. A tab with <code>href</code> is a link, a tab without is a button. Only the current tab is in the tab order: the left and right arrow keys, Home and End move the focus between the tabs, and Enter or Space opens the focused one. When the tabs do not fit, as many as fit show and the rest fold into a &quot;More&quot; <a href="./menu">Menu</a> at the right end (the <code>more</code> message); nothing scrolls. The tabs are taken from the start as long as they fit, so their order never changes. When the current tab is folded, the trigger of the menu shows its name and its double line instead of &quot;More&quot;, and it is the tab in the tab order.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/tabs/" title="Tabs" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/tabs/" target="_blank" rel="noopener">Tabs</a></figcaption></figure>',10)])])}const p=t(s,[["render",d]]);export{u as __pageData,p as default};
